    window.addEventListener('unhandledrejection', e => handleError(e.reason));
    window.addEventListener('keydown', e => { if (e.key === 'Escape') closeDrawer(); });
    window.addEventListener('resize', updateDrawerMode);
    updateDrawerMode();
    refresh().catch(handleError);
